// US layer data loader — reads the EDFacts snapshots generated by
// `npm run ingest`, merges the (optional) CRDC absenteeism snapshot and the
// live Census poverty feed, and exposes one ready-to-render dataset.
//
// Snapshot files ship with the repository, so the dashboard renders even when
// live feeds are degraded; every page surfaces which mode it is in.

import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { getStatePoverty } from "@/lib/feeds/census";
import type {
  AbsenteeismSnapshot,
  AchievementSnapshot,
  DistrictAchRow,
  UsDataset,
  UsStateRecord,
} from "@/lib/types";

const SNAPSHOT_DIR = join(process.cwd(), "data", "snapshots");
const CACHE_TTL_MS = 5 * 60 * 1000;

let cache: { at: number; value: UsDataset | null } | null = null;

function loadSnapshot<T>(file: string): T | null {
  const path = join(SNAPSHOT_DIR, file);
  if (!existsSync(path)) return null;
  try {
    return JSON.parse(readFileSync(path, "utf-8")) as T;
  } catch {
    return null;
  }
}

export async function getUsDataset(): Promise<UsDataset | null> {
  if (process.env.STRESS_FAIL_FEEDS?.includes("us")) return null;
  if (cache && Date.now() - cache.at < CACHE_TTL_MS) return cache.value;

  const achievement = loadSnapshot<AchievementSnapshot>("us-achievement.json");
  if (!achievement) {
    cache = { at: Date.now(), value: null };
    return null;
  }
  const absenteeism = loadSnapshot<AbsenteeismSnapshot>("us-absenteeism.json");
  const poverty = await getStatePoverty();

  const absenteeismByFips = new Map<number, number | null>();
  for (const s of absenteeism?.states ?? []) absenteeismByFips.set(s.fips, s.rate);

  const states: UsStateRecord[] = achievement.states.map((s) => ({
    ...s,
    absenteeism: absenteeismByFips.get(s.fips) ?? null,
    poverty: poverty?.byFips.get(String(s.fips).padStart(2, "0")) ?? null,
  }));

  const districtsByState = new Map<number, DistrictAchRow[]>();
  for (const d of achievement.districts) {
    const list = districtsByState.get(d.state);
    if (list) list.push(d);
    else districtsByState.set(d.state, [d]);
  }

  const absenteeismByDistrict = new Map<string, number>();
  for (const d of absenteeism?.districts ?? []) {
    if (d.rate != null) absenteeismByDistrict.set(d.id, d.rate);
  }

  const value: UsDataset = {
    states,
    districtsByState,
    allDistricts: achievement.districts,
    absenteeismByDistrict,
    meta: {
      achievement: achievement.meta,
      absenteeism: absenteeism?.meta ?? null,
      poverty: poverty?.meta ?? null,
    },
  };
  cache = { at: Date.now(), value };
  return value;
}
